package com.example.starter.domain;

import java.math.BigDecimal;

/**
 * 塔机。ratedLoadTonnes 为额定载荷（吨），吊重超过该值的授权申请即拒绝。
 */
public record Crane(String id, String name, BigDecimal ratedLoadTonnes) {
}

package com.example.starter.domain;

/**
 * 塔机回转重叠区，按圆形区域建模（场地平面坐标系，单位米）。
 */
public record OverlapZone(String id, String name, double centerXM, double centerYM, double radiusM) {

    /**
     * 判断吊钩坐标是否进入该重叠区（含边界）。
     */
    public boolean contains(double hookXM, double hookYM) {
        double dx = hookXM - centerXM;
        double dy = hookYM - centerYM;
        return dx * dx + dy * dy <= radiusM * radiusM;
    }
}

package com.example.starter.domain;

/**
 * 授权状态：ACTIVE=生效中，COMPLETED=作业完成已释放，CANCELLED=已取消释放。
 */
public enum AuthorizationStatus {
    ACTIVE,
    COMPLETED,
    CANCELLED
}

package com.example.starter.domain;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 重叠区作业授权。冲突判定按半开区间 [startTimeUtc, endTimeUtc)；
 * 位姿恰在 endTimeUtc 时刻按授权内处理；releasedAtUtc 为 NULL 表示仍生效。
 */
public record ZoneAuthorization(
        Long id,
        String requestId,
        String fingerprint,
        String craneId,
        String zoneId,
        Instant startTimeUtc,
        Instant endTimeUtc,
        BigDecimal loadTonnes,
        AuthorizationStatus status,
        Instant createdAtUtc,
        Instant releasedAtUtc) {

    /**
     * 判断给定时刻的位姿是否处于本授权保护内：
     * 起止时刻闭区间覆盖（恰结束时刻按授权内），且释放时刻之后的读数不再受保护。
     */
    public boolean coversPoseAt(Instant tsUtc) {
        boolean withinWindow = !tsUtc.isBefore(startTimeUtc) && !tsUtc.isAfter(endTimeUtc);
        boolean notReleasedBefore = releasedAtUtc == null || !tsUtc.isAfter(releasedAtUtc);
        return withinWindow && notReleasedBefore;
    }
}

package com.example.starter.domain;

import java.time.Instant;

/**
 * 塔机位姿读数。按（塔机，采集时刻）去重；乱序到达按 tsUtc 归位。
 */
public record PoseReading(
        Long id,
        String craneId,
        Instant tsUtc,
        double hookXM,
        double hookYM,
        Instant receivedAtUtc) {
}

package com.example.starter.domain;

/**
 * 越限事件状态：OPEN=预警中，BRAKED=已下发制动，RESOLVED=吊钩已退出区域。
 */
public enum BreachStatus {
    OPEN,
    BRAKED,
    RESOLVED
}

package com.example.starter.domain;

import java.time.Instant;

/**
 * 越限预警事件。不可删除、不可修改；持续越限 3 秒触发自动制动。
 */
public record BreachEvent(
        Long id,
        String craneId,
        String zoneId,
        Instant firstDetectedAtUtc,
        Instant lastDetectedAtUtc,
        BreachStatus status,
        Instant resolvedAtUtc,
        Instant createdAtUtc) {
}

package com.example.starter.domain;

import java.time.Instant;

/**
 * 自动制动指令。同一越限事件只下发一次（breachEventId 唯一）。
 */
public record BrakeCommand(
        Long id,
        Long breachEventId,
        String craneId,
        String zoneId,
        Instant issuedAtUtc,
        String reason) {
}

